import {editorRequest} from './project-browser.js';
import {validBuildProfile,buildTargets,profileTarget,mobileSettings,kioskSettings} from './build-profile.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function platformFields(profile){
  const target=profileTarget(profile),m=mobileSettings(profile);
  const select=(field,label,choices,value,mobile=true)=>`<label>${label}<select data-${mobile?'mobile':'field'}="${field}">${choices.map(([id,label])=>`<option value="${id}" ${value===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
  const input=(field,label,value,type='text',limits='')=>`<label>${label}<input data-mobile="${field}" type="${type}" value="${esc(value)}" ${limits}></label>`;
  let fields=select('target','플랫폼',Object.entries(buildTargets).map(([id,t])=>[id,t.label]),target,false);
  if(target==='windows-x64'){const k=kioskSettings(profile);return fields+'<fieldset><legend>부스 / 키오스크</legend>'+['enabled','fullscreen','hideCursor','preventMinimize'].map((key,index)=>'<label><input type="checkbox" data-kiosk="'+key+'" '+(k[key]?'checked':'')+'>'+['키오스크 사용','전체 화면 고정','커서 숨김','최소화 방지'][index]+'</label>').join('')+'<label>무입력 초기화(초)<input type="number" min="0" max="86400" data-kiosk="idleResetSeconds" value="'+k.idleResetSeconds+'"></label></fieldset>';}
  fields+=input('applicationId','앱 ID',m.applicationId,'text','maxlength="200"')+input('versionName','버전',m.versionName,'text','maxlength="80"')+input('versionCode','빌드 번호',m.versionCode,'number','min="1" max="2100000000"')+select('orientation','화면 방향',[['landscape','가로'],['portrait','세로'],['auto','자동']],m.orientation);
  if(target==='ios')return fields+'<span>Mac에서 여는 Xcode 프로젝트</span>';
  fields+=select('format','출력',[['apk','APK'],['aab','AAB']],m.format)+input('minSdk','최소 Android API',m.minSdk,'number','min="26" max="36"')+select('abis','CPU',[['arm64-v8a','ARM64 휴대폰'],['x86_64','x64 에뮬레이터'],['both','ARM64 + x64']],m.abis.length===2?'both':m.abis[0]);
  if(profile.configuration==='release')fields+=input('signingRef','서명 프로필',m.signingRef||'','text','maxlength="40"');return fields;
}
export class BuildPanel{
  constructor(element,{session,openScenes,saveAll,error}){this.element=element;this.hooks={session,openScenes,saveAll,error};this.selected='windows';this.unload=event=>{if(this.dirty){event.preventDefault();event.returnValue='';}};window.addEventListener('beforeunload',this.unload);this.load().catch(error);}
  async request(url,data,method='POST'){return (await editorRequest(url,data===undefined?{}:{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})).json();}
  async load(){this.data=await this.request('/api/build/profiles');this.files=(await this.request('/api/project?recursive=1')).entries.filter(f=>f.kind==='scene');if(!this.data.profiles.some(p=>p.id===this.selected))this.selected=this.data.profiles[0].id;this.dirty=false;this.render();}
  async toolsChoice(){
    if(this.toolsDialog)return false;const dialog=document.createElement('dialog');this.toolsDialog=dialog;dialog.className='build-tools-dialog';
    dialog.innerHTML='<h2>Android 빌드 도구</h2><p>SDK · NDK · Build Tools · 기기 연결 도구</p><a href="https://developer.android.com/studio/terms" target="_blank" rel="noopener noreferrer">Google Android SDK 이용약관 열기</a><label><input type="checkbox" data-sdk-consent>이용약관을 읽었으며 동의해요.</label><footer><button data-sdk-cancel>취소</button><button data-sdk-install class="primary-button" disabled>동의하고 설치</button></footer>';
    document.body.append(dialog);return new Promise(resolve=>{let accepted=false;dialog.onchange=()=>{dialog.querySelector('[data-sdk-install]').disabled=!dialog.querySelector('[data-sdk-consent]').checked;};dialog.onclick=event=>{if(event.target.closest('[data-sdk-install]')&&dialog.querySelector('[data-sdk-consent]').checked){accepted=true;dialog.close();}else if(event.target.closest('[data-sdk-cancel]'))dialog.close();};dialog.onclose=()=>{dialog.remove();this.toolsDialog=null;resolve(accepted);};dialog.showModal();});
  }
  render(){const e=this.element,p=this.data.profiles.find(p=>p.id===this.selected),running=this.job?.status==='running';e.className='build-panel';e.innerHTML=`<aside><header><strong>빌드 프로필</strong><button data-build="delete-profile" title="선택 프로필 삭제" aria-label="선택 프로필 삭제" ${this.data.profiles.length===1?'disabled':''}>−</button><button data-build="duplicate" title="프로필 복제" aria-label="프로필 복제">+</button></header>${this.data.profiles.map(p=>`<button class="${p.id===this.selected?'active':''}" data-profile="${p.id}">${esc(p.name)}<small>${buildTargets[profileTarget(p)].label}</small></button>`).join('')}</aside><section><header><h2>${esc(p.name)}</h2><span>${buildTargets[profileTarget(p)].label}</span></header><div class="build-fields">${platformFields(p)}<label>프로필 이름<input data-field="name" value="${esc(p.name)}" maxlength="80"></label><label>게임 이름<input data-field="productName" value="${esc(p.productName)}" maxlength="80"></label><label>구성<select data-field="configuration"><option value="development" ${p.configuration==='development'?'selected':''}>개발</option><option value="release" ${p.configuration==='release'?'selected':''}>배포</option></select></label><label>창 크기<div class="build-size"><input type="number" data-field="width" aria-label="게임 창 너비" min="320" max="7680" value="${p.width}"><span>×</span><input type="number" data-field="height" aria-label="게임 창 높이" min="240" max="4320" value="${p.height}"></div></label></div>${profileTarget(p)==='android'?`<div class="build-tools"><button data-build="android-tools" ${running?'disabled':''}>Android 도구 준비</button></div>`:''}<div class="build-scenes-heading"><h3>장면</h3><button data-build="add-open">열린 장면 추가</button></div><div class="build-scene-list">${p.scenes.map((s,i)=>`<div draggable="true" data-scene="${i}"><input type="checkbox" data-enabled="${i}" ${s.enabled?'checked':''} aria-label="${esc(s.path)} 포함"><span title="${esc(s.path)}">${esc(s.path)}${s.enabled&&i===p.scenes.findIndex(s=>s.enabled)?'<small>시작 장면</small>':''}</span><button data-up="${i}" ${i===0?'disabled':''} aria-label="${esc(s.path)} 위로">↑</button><button data-down="${i}" ${i===p.scenes.length-1?'disabled':''} aria-label="${esc(s.path)} 아래로">↓</button><button data-remove="${i}" aria-label="${esc(s.path)} 제거">×</button></div>`).join('')}</div><div class="build-add"><select aria-label="빌드에 추가할 장면"><option value="">장면 선택</option>${this.files.filter(f=>!p.scenes.some(s=>s.path===f.path)).map(f=>`<option value="${esc(f.path)}">${esc(f.path)}</option>`).join('')}</select><button data-build="add">추가</button></div><div class="build-progress" role="status"></div><pre class="build-result" tabindex="0"></pre><div class="build-output" ${this.job?.status==='done'&&(this.job.result?.executable||this.job.result?.artifact)?'':'hidden'}><button data-build="run" ${this.job?.result?.executable?'':'hidden'}>게임 실행</button><button data-build="reveal">출력 폴더</button></div><div class="build-device" ${this.job?.result?.artifactType==='apk'?'':'hidden'}><select data-build-device aria-label="Android 기기"><option value="">기기 선택</option>${(this.devices||[]).map(d=>`<option value="${esc(d.serial)}" ${d.state!=='device'?'disabled':''}>${esc(d.model)} · ${esc(d.state)}</option>`).join('')}</select><button data-build="devices">기기 새로 읽기</button><button data-build="deploy" ${this.deploying?'disabled':''}>기기에 설치하고 실행</button></div><footer><span>${this.dirty?'저장하지 않은 변경':''}</span><button data-build="reload" ${running?'disabled':''}>다시 읽기</button><button data-build="save" ${running?'disabled':''}>프로필 저장</button><button data-build="validate" ${running?'disabled':''}>검사</button><button class="primary" data-build="build" ${running?'disabled':''}>모두 저장하고 빌드</button><button data-build="build-run" ${running||profileTarget(p)!=='windows-x64'?'disabled':''}>빌드 후 실행</button><button data-build="cancel" ${running?'':'hidden'}>취소</button></footer></section>`;
    this.renderJob();e.oninput=event=>{const input=event.target;if(input.dataset.mobile){p.mobile=mobileSettings(p);const key=input.dataset.mobile;p.mobile[key]=key==='abis'?(input.value==='both'?['arm64-v8a','x86_64']:[input.value]):input.type==='number'?Number(input.value):input.value;this.dirty=true;this.element.querySelector('footer>span').textContent='저장하지 않은 변경';return;}if(input.dataset.field){const key=input.dataset.field;p[key]=input.type==='number'?Number(input.value):input.value;if(key==='target'&&!p.mobile)p.mobile={...mobileSettings(p),applicationId:'com.hbengine.game'+this.hooks.session.id.replace(/[^a-z0-9]/gi,'')};this.dirty=true;this.element.querySelector('footer>span').textContent='저장하지 않은 변경';if(key==='target'||key==='configuration')this.render();if(key==='name'){this.element.querySelector('h2').textContent=p.name;this.element.querySelector('[data-profile="'+p.id+'"]').firstChild.textContent=p.name;}return;}};e.onchange=event=>{if(event.target.dataset.kiosk){p.kiosk={...kioskSettings(p),[event.target.dataset.kiosk]:event.target.type==='checkbox'?event.target.checked:Number(event.target.value)};this.dirty=true;return;}const input=event.target;if(input.dataset.enabled!==undefined)p.scenes[Number(input.dataset.enabled)].enabled=input.checked;else return;this.dirty=true;this.render();};
    e.onclick=event=>{const b=event.target.closest('button');if(!b)return;const run=async()=>{if(b.dataset.profile){this.selected=b.dataset.profile;return this.render();}for(const [key,delta] of [['up',-1],['down',1]])if(b.dataset[key]!==undefined){const i=Number(b.dataset[key]);[p.scenes[i],p.scenes[i+delta]]=[p.scenes[i+delta],p.scenes[i]];this.dirty=true;return this.render();}if(b.dataset.remove!==undefined){p.scenes.splice(Number(b.dataset.remove),1);this.dirty=true;return this.render();}const action=b.dataset.build;if(action==='android-tools'){if(!await this.toolsChoice()||this.disposed)return;this.job=await this.request('/api/build/tools/android',{acceptLicense:true});this.runAfterBuild=false;this.deployment=null;this.render();this.poll();return;}if(action==='devices'){this.devices=(await this.request('/api/build/devices')).devices;return this.render();}if(action==='deploy'){const serial=this.element.querySelector('[data-build-device]').value;if(!serial)throw Error('설치할 기기를 선택하세요.');this.deploying=true;this.render();try{this.deployment=await this.request('/api/build/deploy',{id:this.job.id,serial});}finally{this.deploying=false;this.render();}return;}if(action==='run'||action==='reveal')return this.request('/api/build/open',{id:this.job.id,action});if(action==='delete-profile'){if(this.data.profiles.length===1)return;this.data.profiles=this.data.profiles.filter(p=>p.id!==this.selected);this.selected=this.data.profiles[0].id;this.dirty=true;return this.render();}if(action==='reload')return this.load();if(action==='duplicate'){if(this.data.profiles.length>=32)throw Error('프로필은 32개까지 만들 수 있어요.');const copy=structuredClone(p);copy.id='profile_'+crypto.randomUUID().slice(0,8);copy.name=copy.name.slice(0,76)+' 복사';this.data.profiles.push(copy);this.selected=copy.id;this.dirty=true;return this.render();}if(action==='add-open'||action==='add'){const paths=action==='add-open'?this.hooks.openScenes():[e.querySelector('.build-add select').value];for(const path of paths)if(path&&!p.scenes.some(s=>s.path===path))p.scenes.push({path,enabled:true});this.dirty=true;return this.render();}if(action==='save')return this.save();if(action==='cancel'){await this.request('/api/build/cancel',{id:this.job.id});return;}if(action==='validate'||action==='build'||action==='build-run'){if(!this.data.profiles.every(validBuildProfile))throw Error('이름·창 크기·실행할 장면을 확인하세요.');if(action!=='validate'&&!await this.hooks.saveAll())return;await this.save();if(this.dirty)throw Error('저장 중 변경한 빌드 설정을 먼저 저장하세요.');this.job=await this.request('/api/build',{profileId:this.selected,expectedRevision:this.data.revision,dryRun:action==='validate'});this.deployment=null;this.runAfterBuild=action==='build-run'&&profileTarget(p)==='windows-x64';this.render();this.poll();}};run().catch(this.hooks.error);};
    e.ondragstart=event=>{const row=event.target.closest('[data-scene]');if(row){event.dataTransfer.setData('application/x-hb-build-scene',row.dataset.scene);event.dataTransfer.effectAllowed='move';}};e.ondragover=event=>{if(event.dataTransfer.types.some(t=>['application/x-hb-build-scene','application/x-hb-assets'].includes(t)))event.preventDefault();};e.ondrop=event=>{if(event.dataTransfer.types.includes('application/x-hb-assets')){event.preventDefault();event.stopPropagation();try{for(const f of JSON.parse(event.dataTransfer.getData('application/x-hb-assets')))if(f.kind==='scene'&&!p.scenes.some(s=>s.path===f.path))p.scenes.push({path:f.path,enabled:true});this.dirty=true;this.render();}catch(error){this.hooks.error(error);}return;}if(!event.dataTransfer.types.includes('application/x-hb-build-scene'))return;const row=event.target.closest('[data-scene]');if(!row)return;const from=Number(event.dataTransfer.getData('application/x-hb-build-scene')),to=Number(row.dataset.scene);if(!Number.isInteger(from)||!p.scenes[from])return;event.preventDefault();p.scenes.splice(to,0,p.scenes.splice(from,1)[0]);this.dirty=true;this.render();};
  }
  async save(){
    const profiles=structuredClone(this.data.profiles),snapshot=JSON.stringify(profiles);
    const task=(this.saveQueue||Promise.resolve()).then(async()=>{
      const value=await this.request('/api/build/profiles',{version:1,profiles,expectedRevision:this.data.revision},'PUT');
      this.data.revision=value.revision;this.data.file=value.file;
      this.dirty=JSON.stringify(this.data.profiles)!==snapshot;
      if(!this.disposed)this.element.querySelector('footer>span').textContent=this.dirty?'저장하지 않은 변경':'';
    });this.saveQueue=task.catch(()=>{});return task;
  }
  renderJob(){if(!this.job)return;const job=this.job;this.element.querySelector('.build-progress').textContent=job.status==='running'?job.stage+'…':job.status==='done'?(job.result?.capability?.ready===false?'환경 준비 필요':'완료'):job.status==='canceled'?'취소됨':'실패';const result=this.element.querySelector('.build-result');result.textContent=job.error||(!job.result?'':job.kind==='android-tools'?`${job.result.packages.length}개 도구 · 설치 완료\n${job.result.sdk}`:`${job.result.files}개 콘텐츠 · C++ ${job.result.nativeModules}개\n시작: ${job.result.startupScene}\n${job.result.executable||job.result.artifact||(job.result.capability?.ready===false?job.result.capability.error:'검사 통과')}`);if(this.deploying)result.textContent+='\n기기에 설치하고 실행 중…';else if(this.deployment)result.textContent+='\n설치: '+(this.deployment.installVerified?'성공':'실패')+' · 앱 시작: '+(this.deployment.activityStarted?'성공':'미확인')+' · 게임 실행: '+(this.deployment.runtimeReady?'확인':'기기 확인 필요');}
  async poll(){clearTimeout(this.timer);try{this.job=await this.request('/api/build/job?id='+this.job.id);if(this.disposed)return;if(this.job.status==='running'){this.renderJob();this.timer=setTimeout(()=>this.poll(),500);}else{this.render();if(this.runAfterBuild&&this.job.status==='done'){this.runAfterBuild=false;await this.request('/api/build/open',{id:this.job.id,action:'run'});}}}catch(error){this.hooks.error(error);}}
  dispose(){this.toolsDialog?.close();window.removeEventListener('beforeunload',this.unload);this.disposed=true;clearTimeout(this.timer);}
}
